'use strict';

function createRecipeBook(initialRecipes) {
  if (!Array.isArray(initialRecipes)) {
    throw new TypeError('initialRecipes must be an array');
  }

  const recipes = new Map();

  function cleanText(value, field) {
    if (typeof value !== 'string' || value.trim().length === 0) {
      throw new TypeError(field + ' must be a non-empty string');
    }
    return value.trim();
  }

  function cleanIngredients(value) {
    if (!Array.isArray(value)) {
      throw new TypeError('ingredients must be an array');
    }
    return value.map((item) => cleanText(item, 'ingredient'));
  }

  function cleanRecipe(value) {
    if (value === null || typeof value !== 'object' || Array.isArray(value)) {
      throw new TypeError('recipe must be an object');
    }
    return {
      id: cleanText(value.id, 'id'),
      title: cleanText(value.title, 'title'),
      ingredients: cleanIngredients(value.ingredients)
    };
  }

  function copy(recipe) {
    return { ...recipe, ingredients: recipe.ingredients };
  }

  for (const value of initialRecipes) {
    const recipe = cleanRecipe(value);
    if (recipes.has(recipe.id)) throw new RangeError('duplicate recipe id');
    recipes.set(recipe.id, recipe);
  }

  return {
    add(value) {
      const recipe = cleanRecipe(value);
      if (recipes.has(recipe.id)) throw new RangeError('duplicate recipe id');
      recipes.set(recipe.id, recipe);
      return copy(recipe);
    },
    get(id) {
      const key = cleanText(id, 'id');
      return recipes.has(key) ? copy(recipes.get(key)) : null;
    },
    update(id, changes) {
      const key = cleanText(id, 'id');
      if (changes === null || typeof changes !== 'object' || Array.isArray(changes)) {
        throw new TypeError('changes must be an object');
      }
      if (Object.prototype.hasOwnProperty.call(changes, 'id')) {
        throw new TypeError('id cannot be updated');
      }
      const title = Object.prototype.hasOwnProperty.call(changes, 'title')
        ? cleanText(changes.title, 'title') : undefined;
      const ingredients = Object.prototype.hasOwnProperty.call(changes, 'ingredients')
        ? cleanIngredients(changes.ingredients) : undefined;
      if (!recipes.has(key)) return null;
      const current = recipes.get(key);
      const next = {
        id: current.id,
        title: title === undefined ? current.title : title,
        ingredients: ingredients === undefined ? [...current.ingredients] : ingredients
      };
      recipes.set(key, next);
      return copy(next);
    },
    remove(id) {
      return recipes.delete(cleanText(id, 'id'));
    },
    list() {
      return Array.from(recipes.values(), copy);
    }
  };
