'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Reflect.ownKeys(api), ['createRecipeBook']);
const { createRecipeBook } = api;

const ingredients = Object.freeze([' flour ', ' water ']);
const initialRecipe = Object.freeze({ id: ' bread ', title: ' Basic Bread ', ingredients, ignored: 1 });
const initial = Object.freeze([initialRecipe]);
const book = createRecipeBook(initial);
assert.deepStrictEqual(Reflect.ownKeys(book), ['add', 'get', 'update', 'remove', 'list']);
assert.deepStrictEqual(initialRecipe, { id: ' bread ', title: ' Basic Bread ', ingredients, ignored: 1 });
assert.deepStrictEqual(book.list(), [
  { id: 'bread', title: 'Basic Bread', ingredients: ['flour', 'water'] }
]);

const callerIngredients = [' tomato ', ' salt '];
const added = book.add({ id: ' soup ', title: ' Tomato Soup ', ingredients: callerIngredients });
assert.deepStrictEqual(added, { id: 'soup', title: 'Tomato Soup', ingredients: ['tomato', 'salt'] });
callerIngredients[0] = 'changed';
added.title = 'changed';
added.ingredients.push('changed');
assert.deepStrictEqual(book.get(' soup '), {
  id: 'soup', title: 'Tomato Soup', ingredients: ['tomato', 'salt']
});
assert.strictEqual(book.get('missing'), null);

const fetched1 = book.get('bread');
const fetched2 = book.get('bread');
assert.notStrictEqual(fetched1, fetched2);
assert.notStrictEqual(fetched1.ingredients, fetched2.ingredients);
fetched1.ingredients[0] = 'changed';
assert.strictEqual(fetched2.ingredients[0], 'flour');

assert.deepStrictEqual(book.update(' bread ', { title: ' Better Bread ' }), {
  id: 'bread', title: 'Better Bread', ingredients: ['flour', 'water']
});
assert.deepStrictEqual(book.update('soup', { ingredients: [] }), {
  id: 'soup', title: 'Tomato Soup', ingredients: []
});
assert.deepStrictEqual(book.list().map((recipe) => recipe.id), ['bread', 'soup']);
assert.strictEqual(book.update('unknown', { title: 'Valid' }), null);

const beforeFailures = book.list();
assert.throws(() => book.add({ id: ' bread ', title: 'Duplicate', ingredients: [] }), RangeError);
assert.throws(() => book.update('bread', { title: 'Valid', ingredients: ['ok', '   '] }), TypeError);
assert.throws(() => book.update('bread', { id: 'new-id' }), TypeError);
assert.deepStrictEqual(book.list(), beforeFailures);

assert.strictEqual(book.remove(' soup '), true);
assert.strictEqual(book.remove('soup'), false);
assert.deepStrictEqual(book.list().map((recipe) => recipe.id), ['bread']);

assert.throws(() => createRecipeBook(null), TypeError);
assert.throws(() => createRecipeBook([null]), TypeError);
assert.throws(() => createRecipeBook([{ id: '', title: 'x', ingredients: [] }]), TypeError);
assert.throws(() => createRecipeBook([{ id: 'x', title: ' ', ingredients: [] }]), TypeError);
assert.throws(() => createRecipeBook([{ id: 'x', title: 'x', ingredients: 'salt' }]), TypeError);
assert.throws(() => createRecipeBook([{ id: 'x', title: 'x', ingredients: [1] }]), TypeError);
assert.throws(() => createRecipeBook([
  { id: 'x', title: 'One', ingredients: [] },
  { id: ' x ', title: 'Two', ingredients: [] }
]), RangeError);
assert.throws(() => book.get('   '), TypeError);
assert.throws(() => book.remove(1), TypeError);
assert.throws(() => book.update('bread', null), TypeError);

